<?php
namespace App\Http\Controllers;
use App\Models\Supplier;use Illuminate\Http\Request;
class SupplierController extends Controller {public function index(Request $r){$rows=Supplier::when($r->q,fn($b,$q)=>$b->where('name','like',"%$q%"))->orderBy('name')->paginate(10)->withQueryString();return view('suppliers.index',['rows'=>$rows]);}public function create(){return view('suppliers.form',['row'=>new Supplier]);}public function store(Request $r){Supplier::create($r->validate(['name'=>'required|string|max:150','phone'=>'nullable|string|max:30','email'=>'nullable|email|max:150']));return redirect()->route('suppliers.index')->with('success','Supplier ditambahkan.');}public function edit(Supplier $supplier){return view('suppliers.form',['row'=>$supplier]);}public function update(Request $r,Supplier $supplier){$supplier->update($r->validate(['name'=>'required|string|max:150','phone'=>'nullable|string|max:30','email'=>'nullable|email|max:150']));return redirect()->route('suppliers.index')->with('success','Supplier diperbarui.');}public function destroy(Supplier $supplier){if($supplier->purchases()->exists())return back()->with('error','Supplier sudah digunakan pada pembelian.');$supplier->delete();return back()->with('success','Supplier dihapus.');}}
